$().ready(function () {

  (listaMenu = []),
    (function () {
      const n = sessionStorage.getItem("_TOKEN"),
        e = (new Date() / 1e3) | 0;
      n
        ? $.ajax({
            async: !1,
            headers: { 
              'Accept': 'application/json',
              'Content-Type': 'application/json' 
            },
            data:JSON.stringify({ Token: n, Key: e, Visible: 1 }),
            type: "POST",
            dataType: "json",
            url: `${sessionStorage.pathWs}/api/MG/ObtieneMenu`,
            beforeSend: function (n) {
              $("#DivLoading").show(), sessionStorage.setItem("listaMenu", 0);
            },
            success: function (n) {
              if (n.Respuesta.length <= 0) window.location = "index.html";
              else {
                const s = n.Respuesta;
                let t = 0,
                  l = 1;
                for (var e in ((strHtml = ""), s))
                  l &&
                    ((l = 0),
                    (t = s[e].Id_Modulo),
                    (strHtml += `<li id="Mod_${t}" class="treeview">\n                                  <a href="#">\n                                    <i class="${s[e].IconoModulo}"></i> \n                                    <span>${s[e].Modulo}</span>\n                                    <span class="pull-right-container">\n                                      <i class="fa fa-angle-left pull-right"></i>\n                                    </span>\n                                  </a>\n                                  <ul class="treeview-menu">`)),
                    s[e].Id_Modulo == t ||
                      ((strHtml += "</ul></li>"),
                      (t = s[e].Id_Modulo),
                      (strHtml += `<li id="Mod_${t}" class="treeview">\n                                  <a href="#">\n                                    <i class="${s[e].IconoModulo}"></i> <span>${s[e].Modulo}</span>\n                                    <span class="pull-right-container">\n                                      <i class="fa fa-angle-left pull-right"></i>\n                                    </span>\n                                  </a>\n                                  <ul class="treeview-menu">`)),
                    (strHtml += `<li id="${s[e].Archivo.substr(
                      0,
                      s[e].Archivo.length - 5
                    )}" parent=${t}><a href="${s[e].Archivo}"><i class="${
                      s[e].IconoArchivo
                    }"></i> <span>${s[e].Descripcion}</span></a></li>`),
                    listaMenu.push([
                      s[e].Archivo,
                      s[e].IconoArchivo,
                      s[e].Descripcion,
                    ]);
                "</li>" !=
                  strHtml.substr(strHtml.length - 5, strHtml.length - 4) &&
                  (strHtml += "</ul></li>"),
                  sessionStorage.setItem(
                    "listaMenu",
                    JSON.stringify(listaMenu)
                  ),
                  sessionStorage.setItem("Rol", s[e].Id_Rol),
                  (document.getElementById("menu_left").innerHTML = strHtml);
              }
            },
            error: function (n) {
              console.log("Error =>", n);
            },
          })
        : (window.location = "index.html");
    })();
});
